class Inbox:
    def __init__(self, items):
        self.items = items

    def __len__(self):               # no __bool__, so truthiness uses __len__
        return len(self.items)


class Always:
    pass                             # neither method: always truthy


class Flag:
    def __bool__(self):              # __bool__ wins over __len__
        return False

    def __len__(self):
        return 5


for name, obj in [("Inbox([])", Inbox([])), ("Inbox([1])", Inbox([1])),
                  ("Always()", Always()), ("Flag()", Flag()),
                  ("[]", []), ("0.0", 0.0), ("None", None)]:
    print(f"bool({name}) =", bool(obj))

