class Bad:
    def __init__(self, n):
        self.n = n

    def __eq__(self, other):
        return isinstance(other, Bad) and self.n == other.n

    def __hash__(self):
        return id(self)              # BUG: equal objects, different hashes


class Good:
    def __init__(self, n):
        self.n = n

    def __eq__(self, other):
        return isinstance(other, Good) and self.n == other.n

    def __hash__(self):
        return hash((self.n,))       # hash exactly the fields used in __eq__


print("Bad(1) == Bad(1):", Bad(1) == Bad(1))
print("set size, Bad :", len({Bad(1), Bad(1)}))
print("set size, Good:", len({Good(1), Good(1)}))

