class Money:
    def __init__(self, cents):
        self.cents = cents

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented    # "not my business", let Python try the other side
        return self.cents == other.cents

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.cents + other.cents)

    def __repr__(self):
        return f"Money({self.cents})"


class Anything:
    def __eq__(self, other):         # a newer type that knows about Money
        print("  Anything.__eq__ was asked")
        return True


