def merge(lists):
    result = []
    lists = [l[:] for l in lists if l]
    while lists:
        for cand in (l[0] for l in lists):
            # candidate must not be in the tail of any list
            if not any(cand in l[1:] for l in lists):
                break
        else:
            raise TypeError("inconsistent hierarchy")
        result.append(cand)
        lists = [[c for c in l if c != cand] for l in lists]
        lists = [l for l in lists if l]
    return result


def c3(cls, bases, table):
    # L[C] = C + merge(L[B1], ..., L[Bn], [B1..Bn])
    parents = bases[cls]
    return [cls] + merge([c3(b, bases, table) for b in parents] + [list(parents)])


