class Base:
    def __init__(self, **kw):
        print("  Base.__init__ kwargs left:", kw)
        super().__init__(**kw)       # object rejects leftover kwargs


class Left(Base):
    def __init__(self, left=0, **kw):
        print("  Left.__init__ takes left =", left)
        super().__init__(**kw)       # forwards the rest to the next in the MRO


class Right(Base):
    def __init__(self, right=0, **kw):
        print("  Right.__init__ takes right =", right)
        super().__init__(**kw)


class Child(Left, Right):
    def __init__(self, **kw):
        print("  Child.__init__")
        super().__init__(**kw)


print("MRO:", [c.__name__ for c in Child.__mro__])
print("Child(left=1, right=2):")
Child(left=1, right=2)               # each class runs exactly once
print("Child(lefft=1) with a typo:")
try:
    Child(lefft=1)
except TypeError as e:
    print("  TypeError:", e)

class Circle:
    def __init__(self, radius):
        self.radius = radius          # goes through the setter: validated

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("radius must be >= 0")
        self._radius = value          # backing field has a different name

    @property
    def area(self):                   # derived, read-only
        return 3.14159 * self._radius ** 2


c = Circle(2)
print("radius:", c.radius, "area:", round(c.area, 2))
c.radius = 3
print("after set, area:", round(c.area, 2))
try:
    c.radius = -1
except ValueError as e:
    print("ValueError:", e)
try:
    c.area = 5
except AttributeError as e:
    print("AttributeError:", e)

c.__dict__["radius"] = 99             # instance value cannot shadow a property
print("shadow attempt, radius still:", c.radius)

