from dataclasses import dataclass, field, replace, asdict


@dataclass(order=True)
class Version:
    major: int
    minor: int = 0
    tags: list = field(default_factory=list, compare=False)  # mutable default done right

    def __post_init__(self):          # validation hook
        if self.major < 0:
            raise ValueError("major must be >= 0")


@dataclass(frozen=True, slots=True)
class Pin:
    name: str
    ver: int


v1, v2 = Version(1, 2), Version(1, 10)
print(v1)                             # generated __repr__
print("v1 == Version(1, 2):", v1 == Version(1, 2))
print("v1 < v2:", v1 < v2)            # order=True compares (major, minor)
print("replace:", replace(v1, minor=5), "| asdict:", asdict(v2))
print("Version hash:", Version.__hash__)   # None: mutable with == is unhashable
p = Pin("lib", 3)
print("hash works for frozen:", hash(p) == hash(Pin("lib", 3)))
try:
    p.ver = 4
except Exception as e:
    print(type(e).__name__, "on assignment")
