from abc import ABC, abstractmethod
from typing import Protocol, runtime_checkable


class Shape(ABC):
    @abstractmethod
    def area(self): ...

    def describe(self):               # concrete method built on the abstract one
        return f"{type(self).__name__} area={self.area()}"


class Square(Shape):
    def __init__(self, s): self.s = s
    def area(self): return self.s * self.s


class Half(Shape):
    pass                              # forgot area()


try:
    Half()
except TypeError as e:
    print("ABC blocks instantiation:", e)
print(Square(3).describe())


@runtime_checkable
class HasArea(Protocol):
    def area(self): ...


class Duck:                           # no inheritance at all
    def area(self): return 7


print("Duck is Shape   :", isinstance(Duck(), Shape))
print("Duck is HasArea :", isinstance(Duck(), HasArea))  # structural, method presence only
Shape.register(Duck)                  # virtual subclass: no checks, no methods inherited
print("after register  :", isinstance(Duck(), Shape), hasattr(Duck(), "describe"))

