class Proxy:
    def __init__(self, target):
        self._t = target
    def __getattr__(self, name):      # forwards normal attributes only
        return getattr(self._t, name)


px = Proxy([1, 2, 3])
print("px.append works:", hasattr(px, "append"))
print("px.__len__() works:", px.__len__())
try:
    len(px)                           # operator lookup skips __getattr__
except TypeError as e:
    print("len(px) TypeError:", e)


